<?php
require_once __DIR__.'/../includes/commerce.php';set_security_headers();header('Content-Type: application/json');header('Cache-Control: no-store');
try{if($_SERVER['REQUEST_METHOD']!=='POST')throw new RuntimeException('Use POST.');az_csrf();$u=az_participant();if(!$u)throw new RuntimeException('Sign in to view your payment.');az_limit('payment.verify',(string)$u['id'],90,900);$order=az_order_public(cms_text('order',40));if(!$order||(int)$order['participant_id']!==(int)$u['id'])throw new RuntimeException('Order unavailable.');
 $order=az_refresh_order($order);if(($_POST['action']??'')==='resume'&&!in_array($order['state'],['PAID','PAID_REVIEW','REFUNDED'],true)){if($order['provider']!=='phonepe'||!az_payment_ready()||$order['environment']!==az_config()['payment_mode']||(int)$order['expires_at']<=time()||!in_array($order['state'],['CREATED','PENDING'],true))throw new RuntimeException('This checkout is no longer available. Check your payment status before creating another registration.');}echo json_encode(['ok'=>true]+az_checkout_response($order)+['url'=>'/dashboard.php']);
}catch(Throwable $e){http_response_code(400);echo json_encode(['ok'=>false,'error'=>$e instanceof PDOException?'Payment status could not be updated. Check your dashboard.':$e->getMessage()]);}
